stylesheets.cssText:
@layer pokeidle-brand {
  .hunt-turbo-dialog { box-sizing: border-box !important; width: min(560px, -24px + 100vw) !important; max-height: calc(100dvh - 24px) !important; padding: 0px !important; border: 1px solid rgb(245, 201, 94) !important; border-radius: 16px !important; background: rgb(8, 28, 43) !important; color: rgb(240, 248, 255) !important; overflow: auto !important; box-shadow: rgba(0, 0, 0, 0.733) 0px 16px 70px !important; }
  .hunt-turbo-dialog::backdrop { background: rgba(2, 10, 20, 0.72); backdrop-filter: blur(3px); }
  .hunt-turbo-dialog .turbo-close { float: right; position: sticky !important; top: 8px !important; margin: 8px 8px -48px 0px !important; z-index: 2 !important; width: 40px !important; height: 40px !important; border: 1px solid rgba(255, 255, 255, 0.6) !important; border-radius: 50% !important; background: rgba(7, 27, 46, 0.93) !important; color: rgb(255, 255, 255) !important; font-style: normal !important; font-variant: normal !important; font-size-adjust: none !important; font-language-override: normal !important; font-kerning: auto !important; font-optical-sizing: auto !important; font-feature-settings: normal !important; font-variation-settings: normal !important; font-weight: normal !important; font-stretch: normal !important; font-size: calc(26px * var(--ui-text-factor, 1)) !important; line-height: normal !important; font-family: Arial !important; }
  .turbo-banner { display: block !important; width: 100% !important; height: auto !important; max-height: calc(100dvh - 184px) !important; object-fit: contain !important; }
  .turbo-footer { padding: 12px 16px !important; display: grid !important; gap: 8px !important; text-align: center !important; }
  .turbo-footer strong, .hunt-turbo-offer strong { color: rgb(255, 218, 118) !important; }
  .turbo-footer small, .hunt-turbo-offer small { display: block !important; font-size: calc(12px * var(--ui-text-factor, 1)) !important; color: rgb(185, 206, 221) !important; }
  .hunt-turbo-dialog button[data-turbo-store], .hunt-turbo-dialog button[data-turbo-confirm], .hunt-turbo-offer button { cursor: pointer; min-height: 44px !important; background: linear-gradient(rgb(255, 224, 149), rgb(235, 172, 53)) !important; border: 1px solid rgb(255, 240, 176) !important; color: rgb(16, 33, 50) !important; border-radius: 8px !important; font-weight: 800 !important; padding: 10px !important; }
  .hunt-turbo-dialog button:focus-visible { outline: rgb(83, 225, 255) solid 3px !important; outline-offset: 2px !important; }
  #hunt-turbo-confirm { padding: 24px !important; }
  #hunt-turbo-confirm p { color: rgb(224, 237, 245) !important; line-height: 1.5 !important; }
  #diamond-offers .hunt-turbo-offer { display: flex !important; flex-direction: column !important; min-width: 0px !important; overflow: hidden !important; gap: 12px !important; padding: 12px !important; }
  #diamond-offers .hunt-turbo-offer .turbo-card-banner { width: 100% !important; max-height: 240px !important; height: auto !important; object-fit: contain !important; }
  .hunt-turbo-offer p { font-size: calc(12px * var(--ui-text-factor, 1)) !important; line-height: 1.45 !important; color: rgb(193, 215, 231) !important; }
  .hunt-turbo-offer b { color: rgb(244, 249, 255) !important; }
  #entry-notices-manual { display: flex; flex-wrap: wrap; gap: 8px; padding: 16px; }
  #entry-notices-manual h3 { flex-basis: 100%; }
  .hunt-turbo-offer button:disabled { opacity: 0.6 !important; cursor: wait; }
  html.hunt-turbo-entry #weekly-pass-welcome { display: none !important; }
}

.pwa-install-button { display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 36px; border: 1px solid rgb(202, 174, 77); border-radius: 9px; background: linear-gradient(135deg, rgb(61, 53, 20), rgb(23, 27, 23)); box-shadow: rgba(255, 241, 163, 0.07) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.333) 0px 7px 18px; color: rgb(255, 233, 141); font-style: normal; font-variant: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 900; font-stretch: normal; font-size: calc(9px * var(--ui-text-factor, 1)); line-height: 1; font-family: Arial; letter-spacing: 0.06em; cursor: pointer; }
.pwa-install-button:hover, .pwa-install-button:focus-visible { border-color: rgb(255, 226, 121); filter: brightness(1.13); outline: rgba(255, 226, 121, 0.333) solid 2px; outline-offset: 2px; }
.pwa-install-button[hidden] { display: none !important; }
.pwa-install-auth { width: 100%; margin: 2px 0px 10px; }
.pwa-install-settings { width: 100%; margin-top: 9px; }
.pwa-dialog { position: fixed; z-index: 470000; inset: 0px; display: grid; place-items: center; padding: 16px; background: rgba(2, 7, 9, 0.85); backdrop-filter: blur(8px); }
.pwa-dialog.hidden { display: none; }
.pwa-dialog > section { display: grid; grid-template-columns: 70px minmax(0px, 1fr); gap: 13px; width: min(430px, -28px + 100vw); padding: 20px; border: 1px solid rgb(215, 187, 88); border-radius: 16px; background: linear-gradient(145deg, rgb(17, 41, 44), rgb(8, 22, 28)); box-shadow: rgba(0, 0, 0, 0.867) 0px 25px 90px; color: rgb(234, 245, 240); }
.pwa-dialog img { width: 66px; height: 66px; filter: drop-shadow(rgba(215, 185, 77, 0.4) 0px 0px 12px); }
.pwa-dialog small { color: rgb(127, 211, 186); font-style: normal; font-variant: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 900; font-stretch: normal; font-size: calc(8px * var(--ui-text-factor, 1)); line-height: 1; font-family: Arial; letter-spacing: 0.15em; }
.pwa-dialog h2 { margin: 6px 0px; color: rgb(255, 240, 177); font-style: normal; font-variant: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 950; font-stretch: normal; font-size: calc(18px * var(--ui-text-factor, 1)); line-height: 1.1; font-family: Arial; }
.pwa-dialog p { margin: 0px; color: rgb(169, 191, 186); font-style: normal; font-variant: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 700; font-stretch: normal; font-size: calc(11px * var(--ui-text-factor, 1)); line-height: 1.5; font-family: Arial; }
.pwa-dialog button { grid-column: 1 / -1; min-height: 39px; border: 1px solid rgb(224, 196, 93); border-radius: 8px; background: rgb(59, 50, 17); color: rgb(255, 234, 160); font-style: normal; font-variant: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 900; font-stretch: normal; font-size: calc(9px * var(--ui-text-factor, 1)); line-height: normal; font-family: Arial; cursor: pointer; }
.pwa-dialog button.secondary { margin-top: -6px; border-color: rgb(64, 92, 92); background: rgb(10, 27, 32); color: rgb(155, 183, 178); }
.pwa-toast { position: fixed; z-index: 480000; right: max(14px,env(safe-area-inset-right)); bottom: max(14px,env(safe-area-inset-bottom)); display: flex; align-items: center; gap: 12px; max-width: min(420px, -28px + 100vw); padding: 12px 14px; border: 1px solid rgb(212, 185, 85); border-radius: 10px; background: rgba(10, 27, 32, 0.93); box-shadow: rgba(0, 0, 0, 0.8) 0px 14px 48px; color: rgb(219, 236, 231); font-style: normal; font-variant: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 800; font-stretch: normal; font-size: calc(10px * var(--ui-text-factor, 1)); line-height: 1.35; font-family: Arial; }
.pwa-toast.hidden { display: none; }
.pwa-toast button { flex: 0 0 auto; min-height: 28px; border: 1px solid rgb(221, 192, 91); border-radius: 6px; background: rgb(59, 50, 17); color: rgb(255, 236, 156); font-style: normal; font-variant: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 900; font-stretch: normal; font-size: calc(8px * var(--ui-text-factor, 1)); line-height: normal; font-family: Arial; cursor: pointer; }
@media (display-mode: standalone) {
  body { overscroll-behavior: none; }
  html { background: rgb(6, 16, 20); }
}
@media (max-width: 560px) {
  .pwa-dialog > section { grid-template-columns: 54px minmax(0px, 1fr); padding: 17px; }
  .pwa-dialog img { width: 50px; height: 50px; }
  .pwa-toast { left: max(10px,env(safe-area-inset-left)); right: max(10px,env(safe-area-inset-right)); bottom: max(10px,env(safe-area-inset-bottom)); }
}

:root { --ink: #18251f; --muted: #728078; --line: #d9e0d8; --paper: #f6f5ee; --panel: #fffdf7; --green: #1d6b45; --green2: #2f8c5c; --gold: #e6b84a; --red: #de5b51; }
* { box-sizing: border-box; }
html, body { margin: 0px; min-height: 100%; background: rgb(232, 235, 227); color: var(--ink); font-family: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif; }
button { font: inherit; }
button:focus-visible, input:focus-visible { outline: rgb(240, 200, 91) solid 3px; outline-offset: 2px; }
body { background-image: radial-gradient(rgb(200, 208, 197) 1px, transparent 1px); background-size: 18px 18px; }
#app { min-height: calc(-28px + 100vh); }
.topbar { height: 74px; padding: 0px 24px; display: flex; align-items: center; gap: 18px; background: rgb(18, 42, 32); color: rgb(255, 255, 255); border-bottom: 4px solid rgb(215, 174, 67); box-shadow: rgba(0, 0, 0, 0.267) 0px 3px 12px; }
.brand { display: flex; align-items: center; gap: 10px; margin-right: auto; }
.brand strong { font-size: calc(22px * var(--ui-text-factor, 1)); letter-spacing: 1.5px; }
.brand small { display: block; color: rgb(233, 201, 95); font-size: calc(9px * var(--ui-text-factor, 1)); letter-spacing: 2.5px; }
.brand-ball { width: 38px; height: 38px; border: 4px solid rgb(255, 255, 255); border-radius: 50%; background: linear-gradient(rgb(228, 90, 80) 0px, rgb(228, 90, 80) 44%, rgb(36, 49, 40) 44%, rgb(36, 49, 40) 56%, rgb(247, 247, 233) 56%); position: relative; }
.brand-ball::after { content: ""; position: absolute; width: 10px; height: 10px; border: 3px solid rgb(255, 255, 255); background: rgb(36, 49, 40); border-radius: 50%; left: 10px; top: 10px; }
.resources { display: flex; gap: 8px; }
.resource { display: flex; align-items: center; gap: 8px; min-width: 116px; padding: 8px 12px; background: rgba(255, 255, 255, 0.07); border: 1px solid rgba(255, 255, 255, 0.12); border-radius: 7px; }
.resource > span { color: rgb(241, 199, 89); font-size: calc(20px * var(--ui-text-factor, 1)); }
.resource small { display: block; font-size: calc(8px * var(--ui-text-factor, 1)); color: rgb(181, 200, 190); letter-spacing: 1px; }
.resource strong { font-size: calc(15px * var(--ui-text-factor, 1)); }
.icon-button { width: 40px; height: 40px; border: 1px solid rgba(255, 255, 255, 0.19); border-radius: 7px; color: white; background: rgba(255, 255, 255, 0.063); font-weight: 900; cursor: pointer; }
.icon-button:hover { background: rgba(255, 255, 255, 0.125); }
.layout { max-width: 1510px; margin: 16px auto; display: grid; grid-template-columns: 264px minmax(520px, 1fr) 264px; gap: 14px; padding: 0px 14px; }
.panel, .world-panel { background: var(--panel); border: 1px solid rgb(207, 214, 205); border-radius: 9px; box-shadow: rgba(38, 58, 41, 0.125) 0px 4px 14px; overflow: hidden; }
.panel-title { height: 45px; padding: 0px 14px; display: flex; align-items: center; justify-content: space-between; color: white; background: rgb(29, 72, 52); border-bottom: 3px solid rgb(216, 179, 79); }
.panel-title span { font-weight: 900; font-size: calc(12px * var(--ui-text-factor, 1)); letter-spacing: 1.3px; }
.panel-title b { padding: 4px 7px; border-radius: 4px; background: rgba(255, 255, 255, 0.086); font-size: calc(9px * var(--ui-text-factor, 1)); letter-spacing: 0.8px; }
.trainer-card { display: flex; gap: 10px; padding: 14px; border-bottom: 1px solid var(--line); }
.portrait { width: 58px; height: 58px; overflow: hidden; border: 3px solid rgb(225, 189, 87); border-radius: 50%; background: rgb(220, 235, 215); position: relative; }
.portrait img { width: 192px; height: 256px; object-fit: none; object-position: 0px 0px; image-rendering: pixelated; transform: scale(0.62); transform-origin: left top; }
.trainer-copy { flex: 1 1 0%; min-width: 0px; }
.trainer-copy strong, .trainer-copy span { display: block; }
.trainer-copy strong { font-size: calc(12px * var(--ui-text-factor, 1)); margin: 5px 0px; }
.trainer-copy span { font-size: calc(9px * var(--ui-text-factor, 1)); color: var(--muted); }
.progress, .hp, .target-hp { height: 7px; background: rgb(223, 228, 223); border-radius: 5px; overflow: hidden; }
.progress { margin-top: 6px; }
.progress i, .hp i, .target-hp i { display: block; height: 100%; width: 42%; background: linear-gradient(90deg, rgb(228, 184, 64), rgb(242, 210, 99)); border-radius: inherit; }
.section-label { padding: 12px 14px 7px; color: rgb(113, 128, 120); font-size: calc(9px * var(--ui-text-factor, 1)); font-weight: 900; letter-spacing: 1.2px; }
.pokemon-card { margin: 0px 12px 7px; padding: 9px; display: flex; gap: 8px; background: rgb(238, 245, 234); border: 1px solid rgb(202, 219, 199); border-radius: 7px; }
.pokemon-sprite { width: 48px; height: 48px; overflow: hidden; background: rgb(213, 231, 210); border-radius: 6px; }
.pokemon-sprite img { width: 96px; height: 128px; object-fit: none; image-rendering: pixelated; transform: scale(0.5); transform-origin: left top; }
.pokemon-card > div:last-child { flex: 1 1 0%; }
.pokemon-card strong, .pokemon-card span, .pokemon-card small { display: block; }
.pokemon-card strong { font-size: calc(12px * var(--ui-text-factor, 1)); }
.pokemon-card span, .pokemon-card small { font-size: calc(9px * var(--ui-text-factor, 1)); color: var(--muted); }
.hp { margin: 5px 0px 3px; }
.hp i { width: 100%; background: rgb(84, 173, 104); }
.toggle-row { display: flex; align-items: center; justify-content: space-between; padding: 8px 14px; cursor: pointer; }
.toggle-row span b, .toggle-row span small { display: block; font-size: calc(10px * var(--ui-text-factor, 1)); }
.toggle-row span small { color: var(--muted); margin-top: 2px; }
.toggle-row input { position: absolute; opacity: 0; }
.toggle-row > i { width: 34px; height: 18px; background: rgb(185, 194, 187); border-radius: 12px; position: relative; transition: 0.2s; }
.toggle-row > i::after { content: ""; position: absolute; width: 14px; height: 14px; left: 2px; top: 2px; background: rgb(255, 255, 255); border-radius: 50%; box-shadow: rgba(0, 0, 0, 0.267) 0px 1px 3px; transition: 0.2s; }
.toggle-row input:checked + i { background: var(--green2); }
.toggle-row input:checked + i::after { left: 18px; }
.upgrade { width: calc(100% - 24px); margin: 0px 12px 7px; padding: 9px 10px; display: flex; align-items: center; justify-content: space-between; border: 1px solid rgb(214, 221, 212); border-radius: 6px; background: white; color: var(--ink); cursor: pointer; }
.upgrade span { display: grid; grid-template-columns: 22px 1fr; align-items: center; text-align: left; }
.upgrade small { grid-column: 2; color: var(--muted); font-size: calc(9px * var(--ui-text-factor, 1)); }
.upgrade em { font-style: normal; font-size: calc(10px * var(--ui-text-factor, 1)); font-weight: 800; color: rgb(149, 109, 18); }
.upgrade em::before { content: "◉ "; color: rgb(214, 165, 47); }
.upgrade:disabled { opacity: 0.48; cursor: not-allowed; }
.world-panel { min-width: 0px; }
.zonebar { height: 54px; padding: 0px 16px; display: flex; align-items: center; justify-content: space-between; background: rgb(255, 255, 255); }
.zonebar small, .zonebar strong { display: block; }
.zonebar small { font-size: calc(8px * var(--ui-text-factor, 1)); color: var(--muted); letter-spacing: 1px; }
.zonebar strong { font-size: calc(15px * var(--ui-text-factor, 1)); }
.idle-status { font-size: calc(10px * var(--ui-text-factor, 1)); letter-spacing: 1px; color: var(--green); display: flex; align-items: center; gap: 6px; }
.idle-status i { width: 8px; height: 8px; border-radius: 50%; background: rgb(73, 181, 108); box-shadow: rgba(73, 181, 108, 0.133) 0px 0px 0px 4px; animation: 1.4s ease 0s infinite normal none running pulse; }
@keyframes pulse { 
  50% { box-shadow: transparent 0px 0px 0px 8px; }
}
#stage { position: relative; background: rgb(26, 46, 37); border-block: 1px solid rgb(37, 62, 49); overflow: hidden; aspect-ratio: 20 / 13; }
canvas { display: block; width: 100%; height: 100%; image-rendering: pixelated; }
#loading { position: absolute; inset: 0px; display: grid; place-items: center; background: rgba(23, 50, 39, 0.91); color: rgb(255, 255, 255); font-weight: 800; }
.hidden { display: none !important; }
.target-card { position: absolute; left: 12px; top: 12px; width: 190px; padding: 8px 10px; background: rgba(255, 254, 241, 0.91); border: 1px solid rgb(36, 74, 52); border-radius: 7px; box-shadow: rgba(0, 0, 0, 0.333) 0px 2px 9px; }
.target-card b, .target-card span { display: block; font-size: calc(10px * var(--ui-text-factor, 1)); }
.target-card span { font-size: calc(8px * var(--ui-text-factor, 1)); color: rgb(101, 114, 107); margin: 2px 0px 5px; }
.target-hp i { width: 100%; background: rgb(88, 173, 99); }
.map-hint { position: absolute; right: 10px; bottom: 10px; padding: 5px 8px; border-radius: 4px; background: rgba(13, 27, 21, 0.72); color: rgb(216, 229, 218); font-size: calc(8px * var(--ui-text-factor, 1)); }
.activity { height: 142px; background: rgb(255, 255, 255); }
.activity-head { height: 36px; padding: 0px 14px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); font-size: calc(10px * var(--ui-text-factor, 1)); letter-spacing: 0.7px; }
.activity-head span { color: var(--muted); font-size: calc(9px * var(--ui-text-factor, 1)); }
.battle-log { height: 106px; overflow: hidden; padding: 5px 14px; }
.log-line { display: grid; grid-template-columns: 52px 19px 1fr; gap: 5px; align-items: center; padding: 4px 0px; border-bottom: 1px dotted rgb(216, 221, 214); font-size: calc(9px * var(--ui-text-factor, 1)); }
.log-line time { color: rgb(139, 150, 144); }
.log-line i { width: 16px; height: 16px; border-radius: 50%; display: grid; place-items: center; background: rgb(230, 242, 229); color: rgb(37, 115, 72); font-style: normal; font-size: calc(8px * var(--ui-text-factor, 1)); }
.log-line.fail i { background: rgb(246, 228, 223); color: rgb(182, 76, 67); }
.helper { margin: 10px 14px 5px; color: var(--muted); font-size: calc(9px * var(--ui-text-factor, 1)); }
.ball-list { padding: 0px 10px; }
.ball-row { display: grid; grid-template-columns: 38px 1fr auto; gap: 8px; align-items: center; padding: 7px 5px; border-bottom: 1px solid rgb(226, 229, 223); }
.ball-icon { width: 34px; height: 34px; overflow: hidden; border-radius: 50%; background: rgb(238, 241, 235); }
.ball-icon img { width: auto; height: auto; max-width: none; image-rendering: pixelated; }
.ball-row strong, .ball-row small { display: block; }
.ball-row strong { font-size: calc(10px * var(--ui-text-factor, 1)); }
.ball-row small { color: var(--muted); font-size: calc(8px * var(--ui-text-factor, 1)); }
.ball-row b { font-size: calc(14px * var(--ui-text-factor, 1)); }
.ball-row.active { background: rgb(245, 241, 220); border-radius: 6px; }
.ball-row.active strong::after { content: "AUTO"; margin-left: 5px; padding: 2px 4px; background: rgb(50, 118, 80); color: white; border-radius: 3px; font-size: calc(7px * var(--ui-text-factor, 1)); }
.summary-grid { display: grid; grid-template-columns: 1fr 1fr; margin: 0px 12px; border: 1px solid var(--line); border-radius: 6px; overflow: hidden; }
.summary-grid div { padding: 8px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.summary-grid div:nth-child(2n) { border-right: 0px; }
.summary-grid div:nth-child(n+3) { border-bottom: 0px; }
.summary-grid small, .summary-grid b { display: block; }
.summary-grid small { font-size: calc(8px * var(--ui-text-factor, 1)); color: var(--muted); }
.summary-grid b { font-size: calc(12px * var(--ui-text-factor, 1)); margin-top: 2px; }
.restock { width: calc(100% - 24px); margin: 10px 12px; padding: 9px; border: 0px; border-radius: 6px; background: rgb(31, 112, 73); color: white; font-size: calc(10px * var(--ui-text-factor, 1)); font-weight: 800; cursor: pointer; }
.restock span { color: rgb(243, 209, 108); }
.source-note { padding: 0px 13px; color: rgb(139, 149, 143); font-size: calc(8px * var(--ui-text-factor, 1)); line-height: 1.45; }
.modal { position: fixed; z-index: 20; inset: 0px; display: grid; place-items: center; padding: 20px; background: rgba(16, 34, 27, 0.74); backdrop-filter: blur(4px); }
.worldmap-panel { width: min(700px, 95vw); background: rgb(249, 248, 239); border: 2px solid rgb(214, 180, 79); border-radius: 10px; overflow: hidden; box-shadow: rgba(0, 0, 0, 0.533) 0px 14px 60px; }
.worldmap-head { display: flex; align-items: center; justify-content: space-between; padding: 16px 20px; background: rgb(25, 62, 46); color: white; }
.worldmap-head small, .worldmap-head strong { display: block; }
.worldmap-head small { font-size: calc(8px * var(--ui-text-factor, 1)); color: rgb(217, 190, 99); letter-spacing: 2px; }
.worldmap-head button { border: 0px; background: rgba(255, 255, 255, 0.09); color: rgb(255, 255, 255); border-radius: 5px; font-size: calc(23px * var(--ui-text-factor, 1)); cursor: pointer; }
.worldmap-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding: 18px; }
.zone-card { min-height: 130px; padding: 14px; border: 2px solid rgb(214, 221, 213); border-radius: 8px; background: rgb(255, 255, 255); text-align: left; cursor: pointer; }
.zone-card.active { border-color: rgb(216, 179, 69); background: rgb(255, 251, 234); }
.zone-card .thumb { float: left; width: 90px; height: 90px; margin-right: 12px; background-repeat: no-repeat; background-position: left top; image-rendering: pixelated; }
.zname { font-weight: 900; margin-top: 12px; }
.zlvl, .zdesc { font-size: calc(10px * var(--ui-text-factor, 1)); color: var(--muted); margin-top: 4px; }
